unified_webgpu_wgsl:
// ============================================================================
// EcoPunk Unified WebGPU Pipeline — Forged & Certified via qualia_core_db::wgsl_forge
// Includes: SPECTRAL_WGSL (CIE 1931 XYZ) + Observer Kernels (0x00..0x05)
//           + SGGX Anisotropic Microflake BRDF + Hydrologic Optics + 16KB ConstituentLUT
// ============================================================================

// σ → CIE 1931 XYZ → linear sRGB (shared by projector + ambient).
// HDR scene path: no sRGB gamma encode — bloom composite applies Reinhard.

fn sigma_to_cie_xyz(sigma: f32) -> vec3<f32> {
    let s = fract(sigma);
    let lambda = 400.0 + (s * 300.0);

    let x1 = 1.056 * exp(-0.5 * pow((lambda - 599.8) / 43.2, 2.0));
    let x2 = 0.362 * exp(-0.5 * pow((lambda - 442.0) / 32.0, 2.0));
    let x3 = -0.065 * exp(-0.5 * pow((lambda - 501.1) / 20.4, 2.0));
    let X = x1 + x2 + x3;

    let y1 = 0.821 * exp(-0.5 * pow((lambda - 568.8) / 46.9, 2.0));
    let y2 = 0.286 * exp(-0.5 * pow((lambda - 530.9) / 16.3, 2.0));
    let Y = y1 + y2;

    let z1 = 1.217 * exp(-0.5 * pow((lambda - 437.0) / 11.8, 2.0));
    let z2 = 0.681 * exp(-0.5 * pow((lambda - 459.0) / 26.0, 2.0));
    let Z = z1 + z2;

    return vec3<f32>(X, Y, Z);
}

fn xyz_to_linear_srgb(xyz: vec3<f32>) -> vec3<f32> {
    let R = 3.2404542 * xyz.x - 1.5371385 * xyz.y - 0.4985314 * xyz.z;
    let G = -0.9692660 * xyz.x + 1.8760108 * xyz.y + 0.0415560 * xyz.z;
    let B = 0.0556434 * xyz.x - 0.2040259 * xyz.y + 1.0572252 * xyz.z;
    return max(vec3<f32>(R, G, B), vec3<f32>(0.0));
}

fn sigma_to_linear_rgb(sigma: f32) -> vec3<f32> {
    return xyz_to_linear_srgb(sigma_to_cie_xyz(sigma));
}

struct SceneUniforms {
    proj: mat4x4<f32>,
    view: mat4x4<f32>,
    camera_pos: vec4<f32>,      // xyz: eye, w: time_seconds
    sun_dir: vec4<f32>,         // xyz: sunDir, w: water_level
    wind_and_clip: vec4<f32>,   // xy: wind_vec, z: clip_plane_z, w: karst_fluting
    isogloss: vec4<f32>,        // x: centerX, y: radius, z: centerZ, w: active
    space_and_mode: vec4<f32>,  // x: kp_index, y: imf_bz, z: f32(observer_mode), w: exposure
};

struct EntityUniforms {
    model: mat4x4<f32>,
    fauna_anim: vec4<f32>,      // x: phase, y: speed, z: gait_code, w: entity_kind
    line_color: vec4<f32>,      // rgba for line rendering
};

@group(0) @binding(0) var<uniform> scene: SceneUniforms;
@group(0) @binding(1) var<storage, read> constituent_lut: array<vec4<u32>, 1024>;
@group(1) @binding(0) var<uniform> entity: EntityUniforms;

const PI_VAL: f32 = 3.14159265359;

// wgsl_forge::observer_kernels::WGSL_KERNEL_PBR microfacet functions
fn distribution_ggx(n: vec3<f32>, h: vec3<f32>, roughness: f32) -> f32 {
    let a = roughness * roughness;
    let a2 = a * a;
    let n_dot_h = max(dot(n, h), 0.0);
    let n_dot_h2 = n_dot_h * n_dot_h;
    let denom = n_dot_h2 * (a2 - 1.0) + 1.0;
    return a2 / (PI_VAL * denom * denom + 0.00001);
}

fn geometry_schlick_ggx(n_dot_v: f32, roughness: f32) -> f32 {
    let r = roughness + 1.0;
    let k = (r * r) / 8.0;
    return n_dot_v / (n_dot_v * (1.0 - k) + k + 0.00001);
}

fn fresnel_schlick(cos_theta: f32, f0: vec3<f32>) -> vec3<f32> {
    return f0 + (vec3<f32>(1.0) - f0) * pow(clamp(1.0 - cos_theta, 0.0, 1.0), 5.0);
}

// shaders::viewport::sggx_microflake.wgsl anisotropic foliage/ground fiber BRDF
fn evaluate_sggx_sheen(n: vec3<f32>, v: vec3<f32>, l: vec3<f32>, sigma_v: f32, sigma_t: f32) -> f32 {
    let h = normalize(v + l);
    let t_fiber = vec3<f32>(0.0, 1.0, 0.0);
    let sv2 = sigma_v * sigma_v;
    let st2 = sigma_t * sigma_t;
    let h_dot_t = dot(h, t_fiber);
    let aniso = sv2 * h_dot_t * h_dot_t + st2 * (1.0 - h_dot_t * h_dot_t);
    return clamp(0.00012 / max(PI_VAL * sv2 * st2 * aniso * aniso, 0.001), 0.0, 0.12) * max(dot(n, l), 0.0);
}

// shaders::viewport::hydrologic_optics.wgsl Henyey-Greenstein & Beer-Lambert
fn henyey_greenstein_phase(cos_theta: f32, g: f32) -> f32 {
    let g2 = g * g;
    let denom = 1.0 + g2 - 2.0 * g * cos_theta;
    return (1.0 - g2) / (4.0 * PI_VAL * pow(max(denom, 0.0001), 1.5));
}

// wgsl_forge::observer_kernels::WGSL_KERNEL_THERMAL ironbow colormap
fn ironbow_thermal(t_norm: f32) -> vec3<f32> {
    let t = clamp(t_norm, 0.0, 1.0);
    let c_cold = vec3<f32>(0.04, 0.08, 0.52);
    let c_mid  = vec3<f32>(0.62, 0.05, 0.78);
    let c_warm = vec3<f32>(0.98, 0.48, 0.04);
    let c_hot  = vec3<f32>(1.0, 0.98, 0.86);
    if (t < 0.33) {
        return mix(c_cold, c_mid, t * 3.0);
    } else if (t < 0.66) {
        return mix(c_mid, c_warm, (t - 0.33) * 3.0);
    }
    return mix(c_warm, c_hot, (t - 0.66) * 3.0);
}

fn aces_film(x: vec3<f32>) -> vec3<f32> {
    let a = 2.51;
    let b = 0.03;
    let c = 2.43;
    let d = 0.59;
    let e = 0.14;
    return clamp((x * (a * x + b)) / (x * (c * x + d) + e), vec3<f32>(0.0), vec3<f32>(1.0));
}

fn hash21(p: vec2<f32>) -> f32 {
    var q = fract(p * vec2<f32>(234.34, 435.345));
    q += dot(q, q + 34.23);
    return fract(q.x * q.y);
}

// Sample dielectric permittivity from the bound 16-KB BankedConstituentLut SSBO
fn sample_lut_dielectric(slot: u32) -> f32 {
    let idx = clamp(slot, 0u, 255u) * 4u + 2u;
    let word = constituent_lut[idx].x;
    let eps_x100 = f32(word & 0xFFFFu);
    return clamp(eps_x100 / 100.0, 1.0, 80.0);
}

struct VertexInput {
    @location(0) position: vec3<f32>,
    @location(1) normal: vec3<f32>,
    @location(2) color: vec3<f32>,
    @location(3) v_meta: vec4<f32>,
};

struct VertexOutput {
    @builtin(position) clip_pos: vec4<f32>,
    @location(0) world_pos: vec3<f32>,
    @location(1) normal: vec3<f32>,
    @location(2) color: vec3<f32>,
    @location(3) v_meta: vec4<f32>,
};

@vertex
fn vs_main(input: VertexInput) -> VertexOutput {
    var pos = input.position;
    var norm = input.normal;
    let entity_kind = i32(round(entity.fauna_anim.w));
    let u_time = scene.camera_pos.w;
    let wind_vec = scene.wind_and_clip.xy;

    // 1. Flora GPU Aeroelastic Bishop-Frame Wind Sway & Leaf Flutter
    if (entity_kind == 1) {
        let h_norm = input.v_meta.x;
        let branch_flex = input.v_meta.y;
        let flutter = input.v_meta.z;
        let wind_mag = length(wind_vec);
        let sway_phase = u_time * 1.65 + entity.model[3][0] * 0.35 + entity.model[3][2] * 0.25;
        let sway_amp = (0.045 * wind_mag) * pow(max(h_norm, 0.0), 1.6) * branch_flex;
        pos.x += wind_vec.x * 0.12 * sway_amp * (0.65 + 0.35 * sin(sway_phase));
        pos.z += wind_vec.y * 0.12 * sway_amp * (0.65 + 0.35 * cos(sway_phase * 0.9));

        if (flutter > 0.2) {
            let fl_phase = u_time * (4.5 + wind_mag * 0.35) + pos.x * 3.1 + pos.y * 2.7;
            let fl_amp = 0.025 * min(wind_mag, 18.0) * flutter;
            pos.x += sin(fl_phase) * fl_amp;
            pos.y += cos(fl_phase * 1.3) * fl_amp * 0.6;
            pos.z += cos(fl_phase * 0.8) * fl_amp;
        }
    }
    // 2. Fauna GPU Articulated Biomechanical Gait Kinematics
    else if (entity_kind == 2) {
        let part_id = input.v_meta.x;
        let side = input.v_meta.y;
        let dist_along = input.v_meta.z;
        let phase = entity.fauna_anim.x;
        let speed = entity.fauna_anim.y;
        let gait = entity.fauna_anim.z;
        let move_factor = clamp(speed / 3.0, 0.15, 1.4);

        if (part_id > 0.5 && part_id < 1.5) {
            pos.y += sin(phase * 2.0) * 0.045 * move_factor * dist_along;
            pos.z += cos(phase) * 0.03 * move_factor * dist_along;
        } else if (part_id > 1.5 && part_id < 2.5) {
            if (gait > 5.5 && gait < 7.5) {
                let flap = sin(phase * 1.8) * select(0.18, 0.55, gait > 6.5);
                pos.y += abs(pos.x) * sin(flap);
            } else {
                let swing = sin(phase + side * 1.57) * 0.22 * move_factor * dist_along;
                pos.z += swing;
                pos.y += max(0.0, cos(phase + side * 1.57)) * 0.08 * move_factor * dist_along;
            }
        } else if (part_id > 2.5 && part_id < 3.5) {
            if (gait < 1.5) {
                let kick = sin(phase) * 0.28 * move_factor * dist_along;
                pos.z -= kick;
                pos.y += max(0.0, cos(phase)) * 0.14 * move_factor * dist_along;
            } else {
                let swing = sin(phase - side * 1.57) * 0.25 * move_factor * dist_along;
                pos.z += swing;
                pos.y += max(0.0, -cos(phase - side * 1.57)) * 0.09 * move_factor * dist_along;
            }
        } else if (part_id > 3.5) {
            let wave = sin(phase * 1.5 - dist_along * 3.5) * 0.18 * dist_along;
            if (gait > 8.5 && gait < 11.5) {
                pos.x += sin(phase * 2.0 - pos.z * 2.5) * 0.16 * (0.3 + 0.7 * dist_along);
            } else {
                pos.x += wave * 0.6;
                pos.y += cos(phase - dist_along * 2.0) * 0.08 * dist_along;
            }
        }
    }
    // 3. Hydrological Water Surface Waves (shaders::viewport::water.wgsl derivatives)
    else if (entity_kind == 3) {
        let w1 = sin(pos.x * 0.45 + u_time * 2.2) * cos(pos.z * 0.35 + u_time * 1.7) * 0.14;
        let w2 = sin((pos.x * 0.8 - pos.z * 0.6) + u_time * 3.4) * 0.06;
        pos.y += w1 + w2;
        norm = normalize(vec3<f32>(-0.22 * cos(pos.x * 0.45 + u_time * 2.2), 1.0, -0.18 * sin(pos.z * 0.35 + u_time * 1.7)));
    }

    let world = entity.model * vec4<f32>(pos, 1.0);
    var out: VertexOutput;
    out.clip_pos = scene.proj * scene.view * world;
    out.world_pos = world.xyz;
    out.normal = normalize((entity.model * vec4<f32>(norm, 0.0)).xyz);
    out.color = input.color;
    out.v_meta = input.v_meta;
    return out;
}

@fragment
fn fs_main(input: VertexOutput) -> @location(0) vec4<f32> {
    let entity_kind = i32(round(entity.fauna_anim.w));
    let observer_mode = i32(round(scene.space_and_mode.z));
    let clip_z = scene.wind_and_clip.z;
    let water_level = scene.sun_dir.w;
    let karst_fluting = scene.wind_and_clip.w;
    let u_time = scene.camera_pos.w;
    let cam_pos = scene.camera_pos.xyz;
    let light_dir = normalize(scene.sun_dir.xyz);

    if (input.world_pos.z > clip_z && entity_kind != 4) {
        discard;
    }

    let n = normalize(input.normal);
    let view_dir = normalize(cam_pos - input.world_pos);
    let n_dot_l = max(dot(n, light_dir), 0.0);
    let n_dot_v = max(dot(n, view_dir), 0.0);

    // Sky Dome (shaders::viewport::sky.wgsl + NOAA SWPC Aurora Australis)
    if (entity_kind == 4) {
        let ray_dir = normalize(input.world_pos - cam_pos);
        let sun_elev = light_dir.y;
        let horizon = clamp(ray_dir.y, 0.0, 1.0);
        let day_zenith = vec3<f32>(0.11, 0.28, 0.56);
        let day_horizon = vec3<f32>(0.55, 0.74, 0.88);
        let dusk_horizon = vec3<f32>(0.88, 0.45, 0.24);
        let day_factor = clamp(sun_elev * 1.8, 0.05, 1.0);
        var sky_col = mix(
            mix(dusk_horizon * day_factor, day_horizon * day_factor, clamp(sun_elev + 0.2, 0.0, 1.0)),
            day_zenith * day_factor,
            pow(horizon, 0.55)
        );
        let sun_dot = max(dot(ray_dir, light_dir), 0.0);
        sky_col += vec3<f32>(1.0, 0.92, 0.72) * pow(sun_dot, 180.0) * 1.4;
        sky_col += vec3<f32>(0.95, 0.75, 0.45) * pow(sun_dot, 12.0) * 0.25;

        let kp = scene.space_and_mode.x;
        if (kp > 3.5 || observer_mode == 5) {
            let aurora_band = sin(ray_dir.x * 6.0 + u_time * 0.8) * cos(ray_dir.z * 5.0 - u_time * 0.5);
            let curtain = smoothstep(0.15, 0.55, ray_dir.y) * (1.0 - smoothstep(0.55, 0.88, ray_dir.y));
            let intensity = select(clamp((kp - 3.5) / 5.5, 0.0, 0.55), 0.65, observer_mode == 5);
            let aurora_col = mix(sigma_to_linear_rgb(0.45), vec3<f32>(0.85, 0.15, 0.65), clamp(ray_dir.y * 1.4, 0.0, 1.0));
            sky_col += aurora_col * curtain * (0.5 + 0.5 * aurora_band) * intensity;
        }
        return vec4<f32>(aces_film(sky_col), 1.0);
    }

    var base_col = input.color;

    // Terrain & 6-Layer SLGA Subsurface Strata (with 16-KB ConstituentLUT lookup)
    if (entity_kind == 0) {
        let is_wall = input.v_meta.z;
        let slope = 1.0 - max(n.y, 0.0);
        if (is_wall < 0.5) {
            if (slope > 0.35) {
                let flute = sin(input.world_pos.x * 3.8 + input.world_pos.z * 3.8) * 0.5 + 0.5;
                let fracture = hash21(floor(input.world_pos.xz * 2.5));
                base_col *= (0.82 + 0.24 * mix(fracture, flute, karst_fluting));
            }
            let dist_above_water = input.world_pos.y - water_level;
            if (dist_above_water >= -0.5 && dist_above_water < 1.35) {
                let wet_factor = 1.0 - clamp(dist_above_water / 1.35, 0.0, 1.0);
                base_col *= (1.0 - 0.38 * wet_factor);
            }
        } else {
            let strata_grain = sin(input.world_pos.y * 14.0 + input.world_pos.x * 0.8) * 0.06;
            base_col += vec3<f32>(strata_grain);
        }
    }

    // Hydrologic Optics Water Shader (shaders::viewport::hydrologic_optics.wgsl + water.wgsl)
    if (entity_kind == 3) {
        let half_vec = normalize(light_dir + view_dir);
        let spec = pow(max(dot(n, half_vec), 0.0), 96.0) * 1.35;
        let fresnel = fresnel_schlick(n_dot_v, vec3<f32>(0.02));
        let hg_backscatter = henyey_greenstein_phase(dot(-view_dir, light_dir), 0.82) * 0.18;
        let deep_water = base_col * (0.55 + hg_backscatter);
        let sky_refl = vec3<f32>(0.42, 0.65, 0.85) * max(0.25, light_dir.y);
        var water_col = mix(deep_water * (0.45 + 0.55 * n_dot_l), sky_refl, fresnel * 0.65) + vec3<f32>(1.0, 0.96, 0.85) * spec;
        if (observer_mode == 4) {
            water_col = vec3<f32>(0.05, 0.22, 0.68);
        }
        return vec4<f32>(aces_film(water_col), 1.0);
    }

    var final_col = base_col;

    // 0x00: WGSL_KERNEL_PBR + SGGX Anisotropic Microflake Sheen + Near-Field Clarity Fog
    if (observer_mode == 0) {
        let h = normalize(light_dir + view_dir);
        let roughness = select(0.76, select(0.54, 0.62, entity_kind == 2), entity_kind != 0);
        let ndf = distribution_ggx(n, h, roughness);
        let g = geometry_schlick_ggx(n_dot_v, roughness) * geometry_schlick_ggx(n_dot_l, roughness);
        let f = fresnel_schlick(max(dot(h, view_dir), 0.0), vec3<f32>(0.04));
        let spec = clamp((ndf * g * f) / max(4.0 * n_dot_v * n_dot_l, 0.02) * n_dot_l * 0.35, vec3<f32>(0.0), vec3<f32>(0.28));
        let sggx_sheen = evaluate_sggx_sheen(n, view_dir, light_dir, 0.22, 0.58) * 0.45;

        let sky_amb = mix(vec3<f32>(0.18, 0.16, 0.14), vec3<f32>(0.26, 0.34, 0.46), 0.5 + 0.5 * n.y);
        var sss = vec3<f32>(0.0);
        if (entity_kind == 1 && input.v_meta.w > 1.5) {
            let back_light = max(dot(view_dir, -light_dir), 0.0);
            sss = base_col * vec3<f32>(0.35, 0.55, 0.18) * pow(back_light, 2.0) * 0.45;
        }

        let sun_radiance = vec3<f32>(1.55, 1.46, 1.32) * max(0.15, light_dir.y);
        let lit = base_col * (sky_amb + sun_radiance * n_dot_l * 0.78) + sun_radiance * (spec + vec3<f32>(sggx_sheen)) + sss;

        let dist = length(input.world_pos - cam_pos);
        let d_eff = max(0.0, dist - 38.0);
        let height_factor = exp(-max(0.0, input.world_pos.y - water_level) * 0.08);
        let fog_factor = clamp(1.0 - exp(-d_eff * 0.0035 * (0.4 + 0.6 * height_factor)), 0.0, 0.65);
        let fog_col = vec3<f32>(0.58, 0.72, 0.84) * max(0.25, light_dir.y);
        final_col = aces_film(mix(lit, fog_col, fog_factor));
    }
    // 0x01: WGSL_KERNEL_TOON (3-Tone Quantization & Silhouette Inking)
    else if (observer_mode == 1) {
        var cel = 0.38;
        if (n_dot_l > 0.68) {
            cel = 1.12;
        } else if (n_dot_l > 0.32) {
            cel = 0.78;
        }
        let rim = smoothstep(0.18, 0.28, n_dot_v);
        final_col = base_col * cel * (0.15 + 0.85 * rim);
    }
    // 0x02: WGSL_KERNEL_WATERCOLOR (Kubelka-Munk Wash & Coffee-Ring Edge Pooling)
    else if (observer_mode == 2) {
        let grain = sin(input.world_pos.x * 4.5) * cos(input.world_pos.z * 4.5) * 0.07;
        let wash = smoothstep(0.08, 0.92, n_dot_l + grain);
        let warm_paper = vec3<f32>(0.98, 0.95, 0.88);
        let pigment = mix(base_col * 0.68, min(vec3<f32>(1.0), base_col * 1.28 + vec3<f32>(0.06, 0.03, 0.0)), wash);
        let edge_pooling = 1.0 - 0.32 * pow(1.0 - n_dot_v, 2.2);
        final_col = mix(warm_paper, pigment * edge_pooling, 0.88);
    }
    // 0x03: WGSL_KERNEL_HUD (GPR Dielectric Contrast from 16-KB ConstituentLUT & Scanlines)
    else if (observer_mode == 3) {
        let lut_slot = u32(clamp(input.v_meta.y, 1.0, 6.0));
        let dielectric_perm = sample_lut_dielectric(lut_slot);
        let gpr_intensity = clamp(dielectric_perm / 40.0, 0.1, 1.0);
        let grid = step(0.93, fract(input.world_pos.x * 0.5)) + step(0.93, fract(input.world_pos.z * 0.5));
        let contour = step(0.92, fract(input.world_pos.y * 0.8));
        let pulse = sin(input.world_pos.y * 6.0 - u_time * 5.0) * 0.5 + 0.5;
        let backing = vec3<f32>(0.02, 0.06, 0.11);
        if (entity_kind == 2) {
            final_col = mix(vec3<f32>(0.95, 0.2, 0.6), vec3<f32>(1.0, 0.85, 0.2), n_dot_l);
        } else if (entity_kind == 1) {
            final_col = mix(backing, vec3<f32>(0.1, 0.92, 0.55), 0.35 + 0.45 * n_dot_l + grid * 0.3);
        } else {
            final_col = mix(backing, vec3<f32>(0.0, 0.88, 1.0) * (0.6 + 0.4 * gpr_intensity), clamp(grid * 0.65 + contour * 0.45 + pulse * 0.15, 0.0, 1.0));
        }
    }
    // 0x04: WGSL_KERNEL_THERMAL (Planck Blackbody Ironbow Pseudocolor)
    else if (observer_mode == 4) {
        var heat = 0.35;
        if (entity_kind == 2) {
            heat = clamp(input.v_meta.w + 0.15 * n_dot_l, 0.0, 1.0);
        } else if (entity_kind == 1) {
            heat = 0.28 + 0.24 * n_dot_l;
        } else {
            heat = clamp(0.18 + n_dot_l * 0.42 + (input.world_pos.y / 30.0) * 0.15, 0.0, 0.85);
        }
        final_col = ironbow_thermal(heat);
    }
    // 0x05: Heliophysics & CIE 1931 Spectral Bioacoustic Wavefield
    else if (observer_mode == 5) {
        let mag_field = abs(sin(input.world_pos.x * 0.25 + input.world_pos.z * 0.15 + u_time * 0.8));
        let bio_col = base_col * (0.45 + 0.65 * n_dot_l);
        let spectral_wave = sigma_to_linear_rgb(mag_field);
        final_col = mix(bio_col, spectral_wave, 0.32);
    }

    if (scene.isogloss.w > 0.5 && entity_kind == 0) {
        let dist_iso = length(input.world_pos.xz - vec2<f32>(scene.isogloss.x, scene.isogloss.z));
        let ring_dist = abs(dist_iso - scene.isogloss.y);
        if (ring_dist < 0.55) {
            let glow = 1.0 - (ring_dist / 0.55);
            final_col = mix(final_col, vec3<f32>(0.0, 0.96, 0.82), glow * 0.75);
        }
    }

    return vec4<f32>(final_col, 1.0);
}

// Overlay Line Pipeline Entry Points (Osteological Skeleton, Vascular Xylem, Trophic Arcs)
struct LineVertexInput {
    @location(0) position: vec3<f32>,
};

struct LineVertexOutput {
    @builtin(position) clip_pos: vec4<f32>,
};

@vertex
fn vs_line(input: LineVertexInput) -> LineVertexOutput {
    var out: LineVertexOutput;
    out.clip_pos = scene.proj * scene.view * entity.model * vec4<f32>(input.position, 1.0);
    return out;
}

@fragment
fn fs_line() -> @location(0) vec4<f32> {
    return entity.line_color;
}

viewport_library_wgsl.acoustic_voxel_cone:
// Acoustic Voxel Cone Tracing WGSL Compute Kernel
//
// Performs continuous acoustic ray/cone marching through a 32x32x32 toroidal
// acoustic absorption volume (rgba8uint).
//
// Frequency bands:
//   R: Low-frequency absorption coefficient (200 Hz anchor)
//   G: Mid-frequency absorption coefficient (1000 Hz anchor)
//   B: High-frequency absorption coefficient (8000 Hz anchor)
//   A: Density / acoustic impedance boundary flag
//
// Step size scaling:
//   dt = max(voxel_size, t * tan(theta / 2))
//
// Volumetric accumulation:
//   T_k = T_{k-1} * (1.0 - alpha_k * dt)
//
// Early termination:
//   Terminates when T < 0.01 across all 3 bands.

struct AcousticConeUniform {
    voxel_size: f32,
    grid_dim: u32,
    cone_angle: f32,
    audibility_threshold: f32,
    max_distance: f32,
    step_limit: u32,
    _pad0: u32,
    _pad1: u32,
};

struct AcousticRayQuery {
    origin: vec3<f32>,
    cone_angle: f32,
    direction: vec3<f32>,
    max_dist: f32,
};

struct AcousticRayResult {
    transmittance: vec3<f32>, // Low (200Hz), Mid (1000Hz), High (8000Hz)
    occlusion: f32,           // 1.0 - average transmittance
    accumulated_distance: f32,
    step_count: u32,
    early_terminated: u32,
    _pad: u32,
};

@group(0) @binding(0) var<uniform> config: AcousticConeUniform;
@group(0) @binding(1) var acoustic_volume: texture_storage_3d<rgba8uint, read>;
@group(0) @binding(2) var<storage, read> ray_queries: array<AcousticRayQuery>;
@group(0) @binding(3) var<storage, read_write> ray_results: array<AcousticRayResult>;

fn sample_toroidal_volume(world_pos: vec3<f32>) -> vec4<f32> {
    let v_float = world_pos / config.voxel_size;
    let v_int = vec3<i32>(floor(v_float));
    let fract_v = fract(v_float);

    var samples: array<vec4<f32>, 8>;
    var idx = 0u;

    // Fetch the 8 cube corners
    for (var z = 0; z <= 1; z++) {
        for (var y = 0; y <= 1; y++) {
            for (var x = 0; x <= 1; x++) {
                let offset = vec3<i32>(x, y, z);
                let coord = v_int + offset;

                // Toroidal modulo: ((coord % 32) + 32) % 32
                let wrapped_coord = vec3<u32>(((coord % 32) + 32) % 32);

                // Fetch and unpack rgba8uint to float [0, 1]
                let raw_val = textureLoad(acoustic_volume, wrapped_coord);
                samples[idx] = vec4<f32>(raw_val) / 255.0;
                idx++;
            }
        }
    }

    // Manual trilinear mix using fract_v
    let mix_x0 = mix(samples[0], samples[1], fract_v.x);
    let mix_x1 = mix(samples[2], samples[3], fract_v.x);
    let mix_x2 = mix(samples[4], samples[5], fract_v.x);
    let mix_x3 = mix(samples[6], samples[7], fract_v.x);
    let mix_y0 = mix(mix_x0, mix_x1, fract_v.y);
    let mix_y1 = mix(mix_x2, mix_x3, fract_v.y);
    return mix(mix_y0, mix_y1, fract_v.z);
}

@compute @workgroup_size(64, 1, 1)
fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {
    let ray_idx = global_id.x;
    if (ray_idx >= arrayLength(&ray_queries)) {
        return;
    }

    let query = ray_queries[ray_idx];
    let dir = normalize(query.direction);
    let angle = select(config.cone_angle, query.cone_angle, query.cone_angle > 0.0);
    let tan_half_theta = tan(angle * 0.5);

    let max_d = select(config.max_distance, query.max_dist, query.max_dist > 0.0);
    let audibility_thresh = select(0.01, config.audibility_threshold, config.audibility_threshold > 0.0);
    let max_steps = select(128u, config.step_limit, config.step_limit > 0u);

    var t = config.voxel_size * 0.5;
    var transmittance = vec3<f32>(1.0, 1.0, 1.0);
    var early_term = 0u;
    var steps = 0u;

    while (t < max_d && steps < max_steps) {
        // Delta t: max(voxel_size, t * tan(theta / 2))
        let delta_t = max(config.voxel_size, t * tan_half_theta);
        let sample_pos = query.origin + dir * t;

        // 8-tap trilinear toroidal fetch
        let absorption = sample_toroidal_volume(sample_pos);
        let alpha = clamp(absorption.rgb, vec3<f32>(0.0), vec3<f32>(1.0));

        // Transmittance compositing across 3 frequency bands:
        // T_k = T_{k-1} * (1.0 - alpha_k * delta_t)
        let decay = clamp(vec3<f32>(1.0) - alpha * delta_t, vec3<f32>(0.0), vec3<f32>(1.0));
        transmittance = transmittance * decay;
        steps++;

        // Early termination when transmittance drops below audibility threshold on all 3 bands
        if (transmittance.x < audibility_thresh &&
            transmittance.y < audibility_thresh &&
            transmittance.z < audibility_thresh) {
            early_term = 1u;
            break;
        }

        t += delta_t;
    }

    let avg_t = (transmittance.x + transmittance.y + transmittance.z) / 3.0;
    let occ = clamp(1.0 - avg_t, 0.0, 1.0);

    ray_results[ray_idx] = AcousticRayResult(
        transmittance,
        occ,
        t,
        steps,
        early_term,
        0u
    );
}

viewport_library_wgsl.emf_volumetric:
// EMF 5D volumetric visualizer — renders 2D slices of the 4D EMF field grid
// (x×y×z×t) with 10D manifold tags mapped to color.
//
// Fragment shader samples a storage buffer containing the flat field grid
// (indexed [t][z][y][x]) and maps:
//   amplitude  → brightness (HDR value)
//   phase      → hue (via σ → CIE XYZ → linear sRGB)
//   manifold.scale + attention_depth → saturation gain
//   manifold.manifold_curvature → rim glow / contour enhancement
//
// @group(0) camera + slice params · @group(1) field grid storage

struct EmfSliceUniform {
    // Grid dimensions.
    nx: u32,
    ny: u32,
    nz: u32,
    nt: u32,
    // Current slice indices.
    slice_z: u32,
    slice_t: u32,
    // Grid bounds: [x_min, x_max, y_min, y_max, z_min, z_max].
    x_min: f32,
    x_max: f32,
    y_min: f32,
    y_max: f32,
    z_min: f32,
    z_max: f32,
    // Display controls.
    amplitude_scale: f32,
    phase_offset: f32,
    manifold_gain: f32,
    _pad: f32,
};

// Per-cell field data: amplitude, phase, frequency + 10D manifold coords.
// Matches the host-side EmfFieldCell struct (48 bytes = 3 f32 + 10 f32 + 1 pad).
struct EmfFieldCell {
    amplitude: f32,
    phase: f32,
    frequency: f32,
    // 10D manifold coordinate.
    scale: f32,
    attention_depth: f32,
    epistemic_weight: f32,
    topological_spin: f32,
    temporal_decay: f32,
    entropy_bias: f32,
    spatial_phase: f32,
    recurrence_frequency: f32,
    density_threshold: f32,
    manifold_curvature: f32,
};

@group(0) @binding(0) var<uniform> params: EmfSliceUniform;
@group(1) @binding(0) var<storage, read> field: array<EmfFieldCell>;

const TWO_PI: f32 = 6.283185307;

// σ → CIE 1931 XYZ → linear sRGB (shared spectral mapping).
fn sigma_to_cie_xyz(sigma: f32) -> vec3<f32> {
    let s = fract(sigma);
    let lambda = 400.0 + (s * 300.0);
    let x1 = 1.056 * exp(-0.5 * pow((lambda - 599.8) / 43.2, 2.0));
    let x2 = 0.362 * exp(-0.5 * pow((lambda - 442.0) / 32.0, 2.0));
    let x3 = -0.065 * exp(-0.5 * pow((lambda - 501.1) / 20.4, 2.0));
    let X = x1 + x2 + x3;
    let y1 = 0.821 * exp(-0.5 * pow((lambda - 568.8) / 46.9, 2.0));
    let y2 = 0.286 * exp(-0.5 * pow((lambda - 530.9) / 16.3, 2.0));
    let Y = y1 + y2;
    let z1 = 1.217 * exp(-0.5 * pow((lambda - 437.0) / 11.8, 2.0));
    let z2 = 0.681 * exp(-0.5 * pow((lambda - 459.0) / 26.0, 2.0));
    let Z = z1 + z2;
    return vec3<f32>(X, Y, Z);
}

fn xyz_to_linear_srgb(xyz: vec3<f32>) -> vec3<f32> {
    let R = 3.2404542 * xyz.x - 1.5371385 * xyz.y - 0.4985314 * xyz.z;
    let G = -0.9692660 * xyz.x + 1.8760108 * xyz.y + 0.0415560 * xyz.z;
    let B = 0.0556434 * xyz.x - 0.2040259 * xyz.y + 1.0572252 * xyz.z;
    return max(vec3<f32>(R, G, B), vec3<f32>(0.0));
}

fn sigma_to_linear_rgb(sigma: f32) -> vec3<f32> {
    return xyz_to_linear_srgb(sigma_to_cie_xyz(sigma));
}

// Map phase (radians) to σ in [0,1) for spectral coloring.
fn phase_to_sigma(phase: f32) -> f32 {
    return fract(phase / TWO_PI);
}

// Sample the field grid at integer (ix, iy) for the current (slice_z, slice_t).
fn sample_field(ix: u32, iy: u32) -> EmfFieldCell {
    let idx = ((params.slice_t * params.nz + params.slice_z) * params.ny + iy) * params.nx + ix;
    return field[idx];
}

// Bilinear sample at normalized UV in [0,1].
fn sample_field_bilinear(uv: vec2<f32>) -> EmfFieldCell {
    let fx = clamp(uv.x, 0.0, 0.999) * f32(params.nx);
    let fy = clamp(uv.y, 0.0, 0.999) * f32(params.ny);
    let ix0 = u32(floor(fx));
    let iy0 = u32(floor(fy));
    let ix1 = min(ix0 + 1u, params.nx - 1u);
    let iy1 = min(iy0 + 1u, params.ny - 1u);
    let tx = fx - f32(ix0);
    let ty = fy - f32(iy0);

    let c00 = sample_field(ix0, iy0);
    let c10 = sample_field(ix1, iy0);
    let c01 = sample_field(ix0, iy1);
    let c11 = sample_field(ix1, iy1);

    var result: EmfFieldCell;
    result.amplitude = mix(mix(c00.amplitude, c10.amplitude, tx), mix(c01.amplitude, c11.amplitude, tx), ty);
    result.phase = mix(mix(c00.phase, c10.phase, tx), mix(c01.phase, c11.phase, tx), ty);
    result.frequency = mix(mix(c00.frequency, c10.frequency, tx), mix(c01.frequency, c11.frequency, tx), ty);
    result.scale = mix(mix(c00.scale, c10.scale, tx), mix(c01.scale, c11.scale, tx), ty);
    result.attention_depth = mix(mix(c00.attention_depth, c10.attention_depth, tx), mix(c01.attention_depth, c11.attention_depth, tx), ty);
    result.epistemic_weight = mix(mix(c00.epistemic_weight, c10.epistemic_weight, tx), mix(c01.epistemic_weight, c11.epistemic_weight, tx), ty);
    result.topological_spin = mix(mix(c00.topological_spin, c10.topological_spin, tx), mix(c01.topological_spin, c11.topological_spin, tx), ty);
    result.temporal_decay = mix(mix(c00.temporal_decay, c10.temporal_decay, tx), mix(c01.temporal_decay, c11.temporal_decay, tx), ty);
    result.entropy_bias = mix(mix(c00.entropy_bias, c10.entropy_bias, tx), mix(c01.entropy_bias, c11.entropy_bias, tx), ty);
    result.spatial_phase = mix(mix(c00.spatial_phase, c10.spatial_phase, tx), mix(c01.spatial_phase, c11.spatial_phase, tx), ty);
    result.recurrence_frequency = mix(mix(c00.recurrence_frequency, c10.recurrence_frequency, tx), mix(c01.recurrence_frequency, c11.recurrence_frequency, tx), ty);
    result.density_threshold = mix(mix(c00.density_threshold, c10.density_threshold, tx), mix(c01.density_threshold, c11.density_threshold, tx), ty);
    result.manifold_curvature = mix(mix(c00.manifold_curvature, c10.manifold_curvature, tx), mix(c01.manifold_curvature, c11.manifold_curvature, tx), ty);
    return result;
}

struct VertexOutput {
    @builtin(position) clip_position: vec4<f32>,
    @location(0) uv: vec2<f32>,
};

@vertex
fn vertex_main(@builtin(vertex_index) vid: u32) -> VertexOutput {
    // Full-screen triangle strip (2 triangles covering [-1,1]²).
    let positions = array<vec2<f32>, 6>(
        vec2<f32>(-1.0, -1.0),
        vec2<f32>(1.0, -1.0),
        vec2<f32>(-1.0, 1.0),
        vec2<f32>(-1.0, 1.0),
        vec2<f32>(1.0, -1.0),
        vec2<f32>(1.0, 1.0),
    );
    let uvs = array<vec2<f32>, 6>(
        vec2<f32>(0.0, 0.0),
        vec2<f32>(1.0, 0.0),
        vec2<f32>(0.0, 1.0),
        vec2<f32>(0.0, 1.0),
        vec2<f32>(1.0, 0.0),
        vec2<f32>(1.0, 1.0),
    );
    var out: VertexOutput;
    let p = positions[vid];
    out.clip_position = vec4<f32>(p, 0.0, 1.0);
    out.uv = uvs[vid];
    return out;
}

@fragment
fn fragment_main(input: VertexOutput) -> @location(0) vec4<f32> {
    let cell = sample_field_bilinear(input.uv);

    // Amplitude → brightness (HDR, scaled).
    let amp = abs(cell.amplitude) * params.amplitude_scale;
    let brightness = clamp(amp, 0.0, 4.0);

    // Phase → hue via spectral mapping.
    let sigma = phase_to_sigma(cell.phase + params.phase_offset);
    let base_rgb = sigma_to_linear_rgb(sigma);

    // Manifold fields modulate saturation and tint.
    let manifold_gain = params.manifold_gain;
    let saturation = clamp(cell.scale * manifold_gain, 0.0, 1.5);
    let luminance = dot(base_rgb, vec3<f32>(0.2126, 0.7152, 0.0722));
    let saturated_rgb = mix(vec3<f32>(luminance), base_rgb, saturation);

    // Curvature → rim glow / contour enhancement.
    let curvature_glow = clamp(abs(cell.manifold_curvature) * manifold_gain, 0.0, 1.0);
    let glow_tint = sigma_to_linear_rgb(phase_to_sigma(cell.spatial_phase));
    let rgb = saturated_rgb * brightness + glow_tint * curvature_glow * 0.3;

    // Alpha: amplitude-based opacity, fades to transparent at zero amplitude.
    let alpha = clamp(brightness * 0.5 + 0.1, 0.0, 1.0);

    return vec4<f32>(rgb, alpha);
}

viewport_library_wgsl.foliage_lod:
// Continuous Multi-Scale Foliage LOD & Bézier Blade Generator (`foliage_lod.wgsl`)
//
// Computes GPU-driven procedural foliage realization:
// - Classifies distance LOD (LOD 0 Bézier, LOD 1 Clump Ribbons, LOD 2 Shells, LOD 3 SGGX)
// - Megapixel Governor: Clamps blade spawn count so total vertices <= 1.5x viewport pixel count
// - Generates cubic Bézier curve control points [p0, p1, p2, p3] under wind load and turgor droop
// - Bounded zero-heap output buffer

struct BladeVertex {
    position: vec4<f32>,       // xyz: world position, w: width
    normal_curve: vec4<f32>,   // xyz: blade surface normal, w: normalized curve parameter t in [0, 1]
};

struct FoliageLodUniform {
    camera_pos: vec4<f32>,     // xyz: camera world pos, w: max view distance (80m)
    viewport_dim: vec4<f32>,   // width_px, height_px, 1/width, 1/height
    wind_vector: vec4<f32>,    // xyz: wind velocity m/s, w: gust phase
    clipmap_center: vec4<f32>, // x, z: clipmap world center, y: cell_size_m, w: max_blade_budget
    view_proj: mat4x4<f32>,
};

struct EcotopeGpuPatch {
    species_mix: vec4<f32>,    // ryegrass, clover, tussock, herbs
    params: vec4<f32>,         // x: culm_height_m, y: LAI, z: turgor_mpa, w: moisture
    trample: vec4<f32>,        // x, z: dir, y: matted_ratio, w: pad
};

@group(0) @binding(0) var<uniform> uniforms: FoliageLodUniform;
@group(0) @binding(1) var<storage, read> patches: array<EcotopeGpuPatch>;
@group(0) @binding(2) var<storage, read_write> blade_vertices: array<BladeVertex>;
@group(0) @binding(3) var<storage, read_write> draw_indirect_args: array<u32>;

// Pseudo-random spatial hash
fn hash21(p: vec2<f32>) -> f32 {
    let q = fract(p * vec2<f32>(123.34, 456.21));
    let d = dot(q, q + 45.32);
    return fract(d);
}

fn hash22(p: vec2<f32>) -> vec2<f32> {
    let n = sin(dot(p, vec2<f32>(41.0, 289.0)));
    return fract(vec2<f32>(262144.0, 32768.0) * n);
}

@compute @workgroup_size(64, 1, 1)
fn foliage_cull_and_generate(@builtin(global_invocation_id) global_id: vec3<u32>) {
    let patch_idx = global_id.x;
    let total_patches = u32(uniforms.clipmap_center.w);
    if (patch_idx >= total_patches) {
        return;
    }

    let cell = patches[patch_idx];
    let cell_size = uniforms.clipmap_center.y;
    let grid_dim = 32u;

    let gx = f32(patch_idx % grid_dim);
    let gz = f32(patch_idx / grid_dim);
    let patch_pos = vec3<f32>(
        uniforms.clipmap_center.x + (gx - 16.0) * cell_size,
        0.0,
        uniforms.clipmap_center.z + (gz - 16.0) * cell_size
    );

    let delta_cam = patch_pos - uniforms.camera_pos.xyz;
    let dist = length(delta_cam);

    // Distance LOD classification
    if (dist >= uniforms.camera_pos.w) {
        return; // Beyond 80m horizon: handled by SGGX terrain shader
    }

    // Megapixel Governor: screen-space solid-angle density clamping
    let total_pixels = uniforms.viewport_dim.x * uniforms.viewport_dim.y;
    let max_budget_per_m2 = (total_pixels * 1.5) / (3.14159 * 80.0 * 80.0);
    let distance_clamped = max(dist, 1.0);
    let screen_density_factor = 1.0 / (distance_clamped * distance_clamped);
    let target_blades = u32(clamp(300.0 * screen_density_factor * 16.0, 2.0, max(max_budget_per_m2, 10.0)));

    let turgor = cell.params.z;
    let height_base = cell.params.x;
    let matted = cell.trample.y;

    // Generate Cosserat Bézier blades in caller output buffer
    for (var b = 0u; b < target_blades; b = b + 1u) {
        let rnd = hash22(vec2<f32>(patch_pos.xz + vec2<f32>(f32(b) * 1.37, f32(b) * 2.89)));
        let blade_root = patch_pos + vec3<f32>(
            (rnd.x - 0.5) * cell_size,
            0.0,
            (rnd.y - 0.5) * cell_size
        );

        // Wind deflection & turgor droop
        let wind_force = uniforms.wind_vector.xyz * (0.6 + 0.4 * sin(uniforms.wind_vector.w + rnd.x * 6.28));
        let droop_factor = (1.5 - min(turgor, 1.5)) * 0.45; // Low turgor increases droop

        let h = height_base * (0.8 + 0.4 * rnd.y);
        let p0 = blade_root;
        let p1 = blade_root + vec3<f32>(0.0, h * 0.35, 0.0);
        let p2 = blade_root + vec3<f32>(wind_force.x * 0.15, h * 0.70 - droop_factor * 0.1, wind_force.z * 0.15);
        let p3 = blade_root + vec3<f32>(
            wind_force.x * 0.35 + (rnd.x - 0.5) * droop_factor,
            h - droop_factor * 0.3,
            wind_force.z * 0.35 + (rnd.y - 0.5) * droop_factor
        );

        // Trample flattening
        var final_tip = p3;
        if (matted > 0.2) {
            final_tip = mix(p3, blade_root + vec3<f32>(cell.trample.x, 0.02, cell.trample.z) * h, matted);
        }

        // Emit 4 vertices along the blade for triangle strip
        let out_base = (patch_idx * 16u + b) * 4u;
        if (out_base + 3u < arrayLength(&blade_vertices)) {
            let width = 0.008 * (1.0 - matted * 0.5);

            blade_vertices[out_base + 0u] = BladeVertex(
                vec4<f32>(p0, width),
                vec4<f32>(0.0, 1.0, 0.0, 0.0)
            );
            blade_vertices[out_base + 1u] = BladeVertex(
                vec4<f32>(p1, width * 0.85),
                vec4<f32>(0.0, 1.0, 0.0, 0.33)
            );
            blade_vertices[out_base + 2u] = BladeVertex(
                vec4<f32>(p2, width * 0.65),
                vec4<f32>(0.0, 1.0, 0.0, 0.66)
            );
            blade_vertices[out_base + 3u] = BladeVertex(
                vec4<f32>(final_tip, width * 0.2),
                vec4<f32>(0.0, 1.0, 0.0, 1.0)
            );
        }
    }
}

viewport_library_wgsl.hydrologic_optics:
// Hydrologic Optics, Radiative Transfer & Dielectric BSDF (`hydrologic_optics.wgsl`)
//
// Bridges high-frequency WebGPU rendering with continuous 10D Electromagnetic Field (EMF)
// transport, CASE-2 water optics, and solid dielectrics (soda-lime glass):
// - Multi-spectral Inherent Optical Properties (IOP)
// - Cauchy / Sellmeier chromatic dispersion
// - Henyey-Greenstein anisotropic Mie particulate scattering
// - Beer-Lambert volume extinction & continuous EMF phase shift
// - Volumetric in-scattering (veiling substrate in turbid post-mining clay waters)
// - Brewster-angle polarization window

struct DielectricVolumeIop {
    ior_spectrum: vec3<f32>,       // [n_red, n_green, n_blue] chromatic dispersion
    _pad0: f32,
    absorption_coeff: vec3<f32>,   // a(λ) in m⁻¹
    _pad1: f32,
    rayleigh_scattering: vec3<f32>,// b_r(λ) in m⁻¹ (molecular ∝ λ⁻⁴)
    _pad2: f32,
    mie_scattering: vec4<f32>,     // [b_r, b_g, b_b, g] in m⁻¹ + Henyey-Greenstein g ∈ [-1, 1]
};

const PI: f32 = 3.14159265359;
const TWO_PI: f32 = 6.28318530718;

// Wavelength standards in micrometers for Cauchy dispersion: Red (0.650 μm), Green (0.532 μm), Blue (0.450 μm).
const LAMBDA_RGB_UM: vec3<f32> = vec3<f32>(0.650, 0.532, 0.450);
// Wavelength standards in meters for EMF phase shifts.
const LAMBDA_RGB_M: vec3<f32> = vec3<f32>(650.0e-9, 532.0e-9, 450.0e-9);

// Cauchy dispersion: n(λ) = A + B / λ² (λ in micrometers).
fn cauchy_dispersion(A: f32, B: f32) -> vec3<f32> {
    let inv_sq = 1.0 / (LAMBDA_RGB_UM * LAMBDA_RGB_UM);
    return vec3<f32>(A + B * inv_sq.x, A + B * inv_sq.y, A + B * inv_sq.z);
}

// Henyey-Greenstein particulate scattering phase function p(θ).
// For forward-peaked suspended silt/clay, g ≈ 0.85–0.92.
fn henyey_greenstein(cos_theta: f32, g: f32) -> f32 {
    let g2 = g * g;
    let denom = 1.0 + g2 - 2.0 * g * cos_theta;
    return (1.0 - g2) / (4.0 * PI * pow(max(denom, 0.0001), 1.5));
}

// Total beam attenuation coefficient c(λ) = a(λ) + b_r(λ) + b_m(λ).
fn beam_attenuation_coeff(iop: DielectricVolumeIop) -> vec3<f32> {
    return iop.absorption_coeff + iop.rayleigh_scattering + iop.mie_scattering.xyz;
}

// Beer-Lambert volume transmittance T(d) = exp(-c(λ) * d).
fn beer_lambert_transmittance(c: vec3<f32>, distance_m: f32) -> vec3<f32> {
    return exp(-c * max(distance_m, 0.0));
}

// Continuous EMF phase shift Δϕ = (2π / λ) * n(λ) * d (in radians, modulo 2π).
fn emf_phase_shift(ior: vec3<f32>, distance_m: f32) -> vec3<f32> {
    let phi = (TWO_PI / LAMBDA_RGB_M) * ior * distance_m;
    return fract(phi / TWO_PI) * TWO_PI;
}

// Wavelength-dependent Schlick Fresnel reflectance with chromatic dispersion.
fn spectral_schlick_fresnel(cos_theta: f32, ior: vec3<f32>) -> vec3<f32> {
    // Air-to-dielectric base reflectance F0 = ((n - 1) / (n + 1))²
    let f0 = ((ior - vec3<f32>(1.0)) / (ior + vec3<f32>(1.0))) * ((ior - vec3<f32>(1.0)) / (ior + vec3<f32>(1.0)));
    let omc = clamp(1.0 - cos_theta, 0.0, 1.0);
    let omc5 = pow(omc, 5.0);
    return f0 + (vec3<f32>(1.0) - f0) * omc5;
}

// Volumetric Subsurface In-Scattering (Backscatter Veil).
// High turbidity (e.g., gold-mining colloidal clay) scatters sunlight back toward the viewer,
// creating an opaque milky ochre veil that obscures the substrate.
fn volumetric_subsurface_backscatter(
    iop: DielectricVolumeIop,
    view_dir: vec3<f32>,
    sun_dir: vec3<f32>,
    water_depth: f32,
    sun_radiance: vec3<f32>,
) -> vec3<f32> {
    let cos_theta = clamp(dot(-view_dir, sun_dir), -1.0, 1.0);
    let phase = henyey_greenstein(cos_theta, iop.mie_scattering.w);
    let c = beam_attenuation_coeff(iop);

    // Radiative transfer in-scattering integration over water depth d:
    // L_in = (b * phase * E_sun / c) * (1 - exp(-c * d))
    let scatter_albedo = select(vec3<f32>(0.0), iop.mie_scattering.xyz / max(c, vec3<f32>(0.0001)), c > vec3<f32>(0.00001));
    let depth_factor = vec3<f32>(1.0) - exp(-c * max(water_depth, 0.0));

    return sun_radiance * scatter_albedo * phase * depth_factor * PI;
}

// Substrate (riverbed/ocean floor) visibility attenuation factor.
// Evaluates direct two-way path extinction combined with the veil penalty.
fn substrate_visibility_factor(
    iop: DielectricVolumeIop,
    water_depth: f32,
) -> f32 {
    let c = beam_attenuation_coeff(iop);
    let avg_c = (c.y + c.z) * 0.5;
    let direct_two_way = exp(-2.0 * avg_c * max(water_depth, 0.0));
    let veil_penalty = 1.0 / (1.0 + iop.mie_scattering.y * water_depth * 1.8);
    return clamp(direct_two_way * veil_penalty, 0.0, 1.0);
}

viewport_library_wgsl.kinematics:
// Kinematics — one softened inverse-square N-body step (gravity / electrostatics) with
// a symplectic-Euler (Euler–Cromer) update.
//
// This is a CERTIFIED forge kernel: its exact CPU oracle and the naga-validation /
// GPU-certify tests live in `wgsl_forge::physics::kinematics`, which embeds this file
// via `include_str!` so there is a single source of truth.
//
// Flat scalar layout (no `vec3` padding): one particle is 8 contiguous `f32`:
//   [ px, py, pz,  vx, vy, vz,  mass, charge ]
//
// DOUBLE-BUFFERED to be deterministic: forces are read from `state_in` only and the
// result is written to `state_out`, so the answer is independent of the order in which
// invocations run (the previous shader read and wrote the SAME buffer — a data race
// that made the result non-deterministic; fixed here).
//
// `params = [ dt, softening², coupling ]`. The pairwise force on i is
//   F_i = coupling · Σ_{j≠i}  q_i·q_j · (r_ij) / (|r_ij|² + softening²)^{3/2},   r_ij = x_i − x_j
// (Plummer softening removes the r→0 singularity, so there is no data-dependent skip
// branch — the kernel is smooth and exactly reproducible by the CPU oracle.) Then
//   v_i ← v_i + (F_i / m_i)·dt ;   x_i ← x_i + v_i·dt   (uses the NEW velocity).
// `coupling` selects the law: +k·qᵢqⱼ for electrostatics (repulsive like-charges),
// −G for gravity (use mass in the charge slot).

@group(0) @binding(0) var<storage, read> state_in: array<f32>;
@group(0) @binding(1) var<storage, read_write> state_out: array<f32>;
@group(0) @binding(2) var<storage, read> params: array<f32>;

@compute @workgroup_size(64)
fn nbody_step(@builtin(global_invocation_id) gid: vec3<u32>) {
    let stride = 8u;
    let count = arrayLength(&state_in) / stride;
    let i = gid.x;
    if (i >= count) {
        return;
    }
    let dt = params[0];
    let soft = params[1];
    let coupling = params[2];

    let bi = i * stride;
    let pix = state_in[bi + 0u];
    let piy = state_in[bi + 1u];
    let piz = state_in[bi + 2u];
    let qi = state_in[bi + 7u];

    var fx = 0.0;
    var fy = 0.0;
    var fz = 0.0;
    for (var j: u32 = 0u; j < count; j = j + 1u) {
        if (j == i) {
            continue;
        }
        let bj = j * stride;
        let rx = pix - state_in[bj + 0u];
        let ry = piy - state_in[bj + 1u];
        let rz = piz - state_in[bj + 2u];
        let r2 = rx * rx + ry * ry + rz * rz + soft;
        // 1 / (r² + soft)^{3/2}.
        let inv = coupling * qi * state_in[bj + 7u] / (r2 * sqrt(r2));
        fx = fx + rx * inv;
        fy = fy + ry * inv;
        fz = fz + rz * inv;
    }

    let mass = state_in[bi + 6u];
    let inv_m = select(0.0, 1.0 / mass, mass != 0.0);
    let vx = state_in[bi + 3u] + fx * inv_m * dt;
    let vy = state_in[bi + 4u] + fy * inv_m * dt;
    let vz = state_in[bi + 5u] + fz * inv_m * dt;

    state_out[bi + 0u] = pix + vx * dt;
    state_out[bi + 1u] = piy + vy * dt;
    state_out[bi + 2u] = piz + vz * dt;
    state_out[bi + 3u] = vx;
    state_out[bi + 4u] = vy;
    state_out[bi + 5u] = vz;
    state_out[bi + 6u] = mass;
    state_out[bi + 7u] = qi;
}

viewport_library_wgsl.sggx_microflake:
// SGGX Anisotropic Microflake Surface BRDF (`sggx_microflake.wgsl`)
//
// Continuous distant ground cover (LOD 3, >80m) optical model:
// - Analytically integrates billions of microscopic grass blade / foliage orientations
//   into a 3D symmetric ellipsoid distribution matrix S (SGGX phase function).
// - Erect high-turgor grass: tangent fiber T = [0, 1, 0] produces velvet-like rim scattering at grazing angles.
// - Wilted or trampled grass: tangent tilts into the horizontal plane, altering specular sheen identically
//   to near-field 3D geometry without rendering sub-pixel blade triangles.

struct SggxParams {
    light_dir: vec4<f32>,       // xyz: normalized light direction towards light, w: light intensity
    view_pos: vec4<f32>,        // xyz: camera world position, w: turgor pressure [0.0, 1.5]
    fiber_tangent: vec4<f32>,   // xyz: macroscopic culm fiber orientation, w: trample matted ratio
    roughness: vec4<f32>,       // x: longitudinal roughness, y: transversal roughness, z: albedo scale, w: pad
};

@group(0) @binding(0) var<uniform> sggx: SggxParams;

const PI: f32 = 3.14159265359;

// Constructs the 3x3 symmetric SGGX matrix S from fiber tangent T and roughness parameters (sigma_v, sigma_t).
// S = sigma_v² (T ⊗ T) + sigma_t² (I - T ⊗ T)
fn compute_sggx_matrix(T: vec3<f32>, sigma_v: f32, sigma_t: f32) -> mat3x3<f32> {
    let sv2 = sigma_v * sigma_v;
    let st2 = sigma_t * sigma_t;
    let t_norm = normalize(T);

    let m00 = sv2 * t_norm.x * t_norm.x + st2 * (1.0 - t_norm.x * t_norm.x);
    let m01 = (sv2 - st2) * t_norm.x * t_norm.y;
    let m02 = (sv2 - st2) * t_norm.x * t_norm.z;

    let m10 = m01;
    let m11 = sv2 * t_norm.y * t_norm.y + st2 * (1.0 - t_norm.y * t_norm.y);
    let m12 = (sv2 - st2) * t_norm.y * t_norm.z;

    let m20 = m02;
    let m21 = m12;
    let m22 = sv2 * t_norm.z * t_norm.z + st2 * (1.0 - t_norm.z * t_norm.z);

    return mat3x3<f32>(
        vec3<f32>(m00, m10, m20),
        vec3<f32>(m01, m11, m21),
        vec3<f32>(m02, m12, m22)
    );
}

// SGGX microflake normal distribution function D(wh) = 1 / (pi * sqrt(det(S)) * (wh^T * S^-1 * wh)^2)
fn sggx_distribution(wh: vec3<f32>, S: mat3x3<f32>) -> f32 {
    let det = S[0][0] * (S[1][1] * S[2][2] - S[1][2] * S[2][1])
            - S[0][1] * (S[1][0] * S[2][2] - S[1][2] * S[2][0])
            + S[0][2] * (S[1][0] * S[2][1] - S[1][1] * S[2][0]);

    let inv_det = 1.0 / max(det, 1e-6);

    // Compute cofactor matrix / inverse
    let c00 = (S[1][1] * S[2][2] - S[1][2] * S[2][1]) * inv_det;
    let c01 = (S[0][2] * S[2][1] - S[0][1] * S[2][2]) * inv_det;
    let c02 = (S[0][1] * S[1][2] - S[0][2] * S[1][1]) * inv_det;

    let c10 = c01;
    let c11 = (S[0][0] * S[2][2] - S[0][2] * S[2][0]) * inv_det;
    let c12 = (S[0][2] * S[1][0] - S[0][0] * S[1][2]) * inv_det;

    let c20 = c02;
    let c21 = c12;
    let c22 = (S[0][0] * S[1][1] - S[0][1] * S[1][0]) * inv_det;

    let S_inv = mat3x3<f32>(
        vec3<f32>(c00, c10, c20),
        vec3<f32>(c01, c11, c21),
        vec3<f32>(c02, c12, c22)
    );

    let s_wh = S_inv * wh;
    let quad = dot(wh, s_wh);
    let denom = PI * sqrt(max(det, 1e-6)) * quad * quad;

    return 1.0 / max(denom, 1e-5);
}

// Projected area in direction V: sigma(V) = sqrt(V^T * S * V)
fn sggx_projected_area(V: vec3<f32>, S: mat3x3<f32>) -> f32 {
    let sv = S * V;
    return sqrt(max(dot(V, sv), 1e-6));
}

// Evaluates SGGX BRDF reflection for distant terrain canopy
fn evaluate_sggx_ground_brdf(
    world_pos: vec3<f32>,
    terrain_normal: vec3<f32>,
    albedo: vec3<f32>,
) -> vec3<f32> {
    let V = normalize(sggx.view_pos.xyz - world_pos);
    let L = normalize(sggx.light_dir.xyz);
    let H = normalize(V + L);

    // Adjust fiber tangent based on turgor pressure and trample matted ratio
    let turgor = sggx.view_pos.w;
    let matted = sggx.fiber_tangent.w;

    var effective_tangent = sggx.fiber_tangent.xyz;
    if (matted > 0.2) {
        // Flattened horizontally by vehicle/feet
        effective_tangent = normalize(vec3<f32>(effective_tangent.x, 0.05, effective_tangent.z));
    } else if (turgor < 0.25) {
        // Wilted droop: isotropic spread
        effective_tangent = normalize(mix(vec3<f32>(0.0, 1.0, 0.0), vec3<f32>(0.7, 0.1, 0.7), 1.0 - turgor * 4.0));
    }

    let sigma_v = sggx.roughness.x; // e.g. 0.15 (smooth along blade)
    let sigma_t = sggx.roughness.y; // e.g. 0.55 (rough across blade)

    let S = compute_sggx_matrix(effective_tangent, sigma_v, sigma_t);

    let D = sggx_distribution(H, S);
    let sigma_V = sggx_projected_area(V, S);
    let sigma_L = sggx_projected_area(L, S);

    // Smith shadowing-masking for microflakes: G = 1 / (sigma_V + sigma_L)
    let G = 1.0 / max(sigma_V + sigma_L, 1e-4);

    let cos_theta_d = dot(L, H);
    let F0 = 0.04; // 4% dielectric Fresnel for plant cuticle wax
    let F = F0 + (1.0 - F0) * pow(1.0 - max(cos_theta_d, 0.0), 5.0);

    let specular_brdf = (D * F * G) * 0.25;
    let diffuse_brdf = albedo * (1.0 / PI) * max(dot(terrain_normal, L), 0.0);

    return (diffuse_brdf + vec3<f32>(specular_brdf)) * sggx.light_dir.w;
}

viewport_library_wgsl.sky:
// Low-cost analytic sky. Camera projection, sun direction/radiance and ambient level all come
// from the scene camera uniform, so the background tracks the same lighting state as the meshes.
struct Camera {
    view_projection: mat4x4<f32>,
    tail: vec4<f32>,
    rest: array<vec4<f32>, 3>,
};
@group(0) @binding(0) var<uniform> camera: Camera;

struct VertexOutput {
    @builtin(position) position: vec4<f32>,
    @location(0) ray: vec3<f32>,
};

fn camera_forward() -> vec3<f32> {
    return safe_normalize(camera.rest[1].xyz - camera.rest[0].yzw, vec3<f32>(0.0, 0.0, -1.0));
}

fn camera_right(forward: vec3<f32>) -> vec3<f32> {
    var reference_up = vec3<f32>(0.0, 1.0, 0.0);
    if (abs(forward.y) > 0.999) {
        reference_up = vec3<f32>(0.0, 0.0, 1.0);
    }
    return safe_normalize(cross(forward, reference_up), vec3<f32>(1.0, 0.0, 0.0));
}

fn camera_up(forward: vec3<f32>, right: vec3<f32>) -> vec3<f32> {
    return safe_normalize(cross(right, forward), vec3<f32>(0.0, 1.0, 0.0));
}

fn safe_normalize(value: vec3<f32>, fallback: vec3<f32>) -> vec3<f32> {
    let magnitude_squared = dot(value, value);
    if (magnitude_squared > 1e-10 && magnitude_squared < 1e20) {
        return value * inverseSqrt(magnitude_squared);
    }
    return fallback;
}

@vertex
fn vertex_main(@builtin(vertex_index) index: u32) -> VertexOutput {
    let x = f32((index << 1u) & 2u);
    let y = f32(index & 2u);
    let ndc = vec2<f32>(x * 2.0 - 1.0, 1.0 - y * 2.0);
    let forward = camera_forward();
    let right = camera_right(forward);
    let up = camera_up(forward, right);

    // Recover FOV and aspect from the rows of the view-projection matrix. The row norms cancel
    // camera rotation, so this remains exact for the current perspective camera without another
    // uniform or an inverse matrix.
    let horizontal = vec3<f32>(
        camera.view_projection[0].x,
        camera.view_projection[1].x,
        camera.view_projection[2].x
    );
    let vertical = vec3<f32>(
        camera.view_projection[0].y,
        camera.view_projection[1].y,
        camera.view_projection[2].y
    );
    let vertical_scale = max(length(vertical), 1e-5);
    let aspect = vertical_scale / max(length(horizontal), 1e-5);
    let tan_half_fov = 1.0 / vertical_scale;

    var output: VertexOutput;
    output.position = vec4<f32>(ndc, 1.0, 1.0);
    output.ray = forward
        + right * (ndc.x * aspect * tan_half_fov)
        + up * (ndc.y * tan_half_fov);
    return output;
}

@fragment
fn fragment_main(input: VertexOutput) -> @location(0) vec4<f32> {
    let ray = safe_normalize(input.ray, vec3<f32>(0.0, 0.0, -1.0));
    let sun = safe_normalize(vec3<f32>(camera.rest[1].w, camera.rest[2].xy), vec3<f32>(0.0, 1.0, 0.0));
    let sun_radiance = max(camera.rest[2].z, 0.0);
    let ambient = clamp(camera.rest[2].w, 0.0, 1.0);

    // Authored day/night transition with a warm horizon near the sunset sun elevation.
    let daylight = smoothstep(0.12, 0.38, ambient);
    let dusk = daylight * (1.0 - smoothstep(0.18, 0.62, sun.y));
    let night_zenith = vec3<f32>(0.008, 0.018, 0.055);
    let day_zenith = vec3<f32>(0.055, 0.22, 0.52);
    let dusk_zenith = vec3<f32>(0.12, 0.16, 0.30);
    let night_horizon = vec3<f32>(0.035, 0.060, 0.14);
    let day_horizon = vec3<f32>(0.58, 0.73, 0.88);
    let dusk_horizon = vec3<f32>(0.92, 0.34, 0.14);
    let day_night_zenith = mix(night_zenith, day_zenith, daylight);
    let day_night_horizon = mix(night_horizon, day_horizon, daylight);
    let zenith = mix(day_night_zenith, dusk_zenith, dusk);
    let horizon = mix(day_night_horizon, dusk_horizon, dusk);
    let horizon_weight = smoothstep(-0.16, 0.56, ray.y);
    let below_horizon = 1.0 - smoothstep(-0.52, -0.015, ray.y);
    let sky = mix(horizon, zenith, horizon_weight);
    let ground_haze = mix(vec3<f32>(0.035, 0.040, 0.045), horizon, 0.5);
    var color = mix(sky, ground_haze, below_horizon);

    let sun_cos = dot(ray, sun);
    let disk = smoothstep(cos(0.010), cos(0.004), sun_cos)
        * smoothstep(-0.08, 0.02, sun.y);
    let halo = pow(max(sun_cos, 0.0), 48.0) * 0.055;
    let moon_color = vec3<f32>(0.48, 0.62, 1.0);
    let day_sun_color = vec3<f32>(1.0, 0.84, 0.64);
    let dusk_sun_color = vec3<f32>(1.0, 0.34, 0.12);
    let sun_color = mix(mix(moon_color, day_sun_color, daylight), dusk_sun_color, dusk);
    color += sun_color * (disk * sun_radiance + halo * min(sun_radiance, 1.5));
    return vec4<f32>(color, 1.0);
}

viewport_library_wgsl.spectral:
// σ → CIE 1931 XYZ → linear sRGB (shared by projector + ambient).
// HDR scene path: no sRGB gamma encode — bloom composite applies Reinhard.

fn sigma_to_cie_xyz(sigma: f32) -> vec3<f32> {
    let s = fract(sigma);
    let lambda = 400.0 + (s * 300.0);

    let x1 = 1.056 * exp(-0.5 * pow((lambda - 599.8) / 43.2, 2.0));
    let x2 = 0.362 * exp(-0.5 * pow((lambda - 442.0) / 32.0, 2.0));
    let x3 = -0.065 * exp(-0.5 * pow((lambda - 501.1) / 20.4, 2.0));
    let X = x1 + x2 + x3;

    let y1 = 0.821 * exp(-0.5 * pow((lambda - 568.8) / 46.9, 2.0));
    let y2 = 0.286 * exp(-0.5 * pow((lambda - 530.9) / 16.3, 2.0));
    let Y = y1 + y2;

    let z1 = 1.217 * exp(-0.5 * pow((lambda - 437.0) / 11.8, 2.0));
    let z2 = 0.681 * exp(-0.5 * pow((lambda - 459.0) / 26.0, 2.0));
    let Z = z1 + z2;

    return vec3<f32>(X, Y, Z);
}

fn xyz_to_linear_srgb(xyz: vec3<f32>) -> vec3<f32> {
    let R = 3.2404542 * xyz.x - 1.5371385 * xyz.y - 0.4985314 * xyz.z;
    let G = -0.9692660 * xyz.x + 1.8760108 * xyz.y + 0.0415560 * xyz.z;
    let B = 0.0556434 * xyz.x - 0.2040259 * xyz.y + 1.0572252 * xyz.z;
    return max(vec3<f32>(R, G, B), vec3<f32>(0.0));
}

fn sigma_to_linear_rgb(sigma: f32) -> vec3<f32> {
    return xyz_to_linear_srgb(sigma_to_cie_xyz(sigma));
}

viewport_library_wgsl.swe_solver:
// 2.5D Shallow Water Equations (SWE) Compute Kernel (`swe_solver.wgsl`)
//
// Solves non-linear depth-averaged Saint-Venant equations with:
// - Conservation of Mass: ∂h/∂t + ∂(hu)/∂x + ∂(hv)/∂y = Rain - Infiltration
// - Conservation of Momentum: ∂(hu)/∂t + ∂(hu² + 0.5gh²)/∂x + ∂(huv)/∂y = -gh(∂z_b/∂x) - τ_bx/ρ + ν∇²(hu)
// - Hydrostatic reconstruction (Kurganov-Petrova central-upwind flux) for well-balanced lake-at-rest state
// - Semi-implicit Manning friction regularization: τ_b = ρ * g * n² * |u| * u / h^(1/3)
// - Wet/dry interface desingularization with threshold ε_h = 1e-4 m

struct SweParams {
    grid_dim: vec2<u32>,        // Width, Height of grid
    dx: f32,                    // Spatial step in meters
    dt: f32,                    // Time step in seconds
    gravity: f32,               // 9.80665 m/s²
    manning_n: f32,             // Bed roughness coefficient (e.g. 0.035 for natural channel)
    rain_rate: f32,             // Net precipitation in m/s
    infiltration: f32,          // Soil infiltration loss in m/s
    viscosity: f32,             // Kinematic eddy viscosity m²/s
    _pad0: f32,
    _pad1: f32,
    _pad2: f32,
};

@group(0) @binding(0) var<uniform> params: SweParams;
// State format: RGBA32F -> x: water depth h, y: momentum hu, z: momentum hv, w: passive tracer (CDOM/tannin)
@group(0) @binding(1) var state_curr: texture_2d<f32>;
// Bed elevation format: RG32F -> x: bed height z_b, y: local roughness multiplier
@group(0) @binding(2) var bed_topo: texture_2d<f32>;
// Output next state
@group(0) @binding(3) var state_next: texture_storage_2d<rgba32float, write>;

const EPSILON_H: f32 = 0.0001; // 0.1 mm wet-dry threshold

// Reads water state clamped to boundary
fn sample_state(coord: vec2<i32>) -> vec4<f32> {
    let clamped = clamp(coord, vec2<i32>(0), vec2<i32>(params.grid_dim) - vec2<i32>(1));
    return textureLoad(state_curr, clamped, 0);
}

// Reads bed topography clamped to boundary
fn sample_bed(coord: vec2<i32>) -> vec2<f32> {
    let clamped = clamp(coord, vec2<i32>(0), vec2<i32>(params.grid_dim) - vec2<i32>(1));
    return textureLoad(bed_topo, clamped, 0).xy;
}

// Computes 1D physical flux vector [F_h, F_hu, F_hv]
fn physical_flux_x(h: f32, hu: f32, hv: f32, g: f32) -> vec3<f32> {
    if (h <= EPSILON_H) {
        return vec3<f32>(0.0);
    }
    let u = hu / h;
    let v = hv / h;
    return vec3<f32>(
        hu,
        hu * u + 0.5 * g * h * h,
        hu * v
    );
}

fn physical_flux_y(h: f32, hu: f32, hv: f32, g: f32) -> vec3<f32> {
    if (h <= EPSILON_H) {
        return vec3<f32>(0.0);
    }
    let u = hu / h;
    let v = hv / h;
    return vec3<f32>(
        hv,
        hv * u,
        hv * v + 0.5 * g * h * h
    );
}

// Kurganov-Petrova central-upwind numerical flux with hydrostatic reconstruction
fn compute_interface_flux_x(
    h_L: f32, hu_L: f32, hv_L: f32, zb_L: f32,
    h_R: f32, hu_R: f32, hv_R: f32, zb_R: f32,
    g: f32
) -> vec3<f32> {
    // Hydrostatic reconstruction to maintain lake-at-rest stability
    let zb_edge = max(zb_L, zb_R);
    let h_L_star = max(0.0, h_L + zb_L - zb_edge);
    let h_R_star = max(0.0, h_R + zb_R - zb_edge);

    if (h_L_star <= EPSILON_H && h_R_star <= EPSILON_H) {
        return vec3<f32>(0.0);
    }

    let u_L = select(0.0, hu_L / max(h_L, EPSILON_H), h_L > EPSILON_H);
    let u_R = select(0.0, hu_R / max(h_R, EPSILON_H), h_R > EPSILON_H);

    let c_L = sqrt(g * h_L_star);
    let c_R = sqrt(g * h_R_star);

    // Wave propagation speeds
    let a_plus = max(0.0, max(u_L + c_L, u_R + c_R));
    let a_minus = min(0.0, min(u_L - c_L, u_R - c_R));
    let denom = a_plus - a_minus;

    if (denom <= 1e-6) {
        return vec3<f32>(0.0);
    }

    let hu_L_star = h_L_star * u_L;
    let hu_R_star = h_R_star * u_R;
    let hv_L_star = select(0.0, (h_L_star / max(h_L, EPSILON_H)) * hv_L, h_L > EPSILON_H);
    let hv_R_star = select(0.0, (h_R_star / max(h_R, EPSILON_H)) * hv_R, h_R > EPSILON_H);

    let F_L = physical_flux_x(h_L_star, hu_L_star, hv_L_star, g);
    let F_R = physical_flux_x(h_R_star, hu_R_star, hv_R_star, g);

    let U_L = vec3<f32>(h_L_star, hu_L_star, hv_L_star);
    let U_R = vec3<f32>(h_R_star, hu_R_star, hv_R_star);

    return (a_plus * F_L - a_minus * F_R + a_plus * a_minus * (U_R - U_L)) / denom;
}

fn compute_interface_flux_y(
    h_B: f32, hu_B: f32, hv_B: f32, zb_B: f32,
    h_T: f32, hu_T: f32, hv_T: f32, zb_T: f32,
    g: f32
) -> vec3<f32> {
    let zb_edge = max(zb_B, zb_T);
    let h_B_star = max(0.0, h_B + zb_B - zb_edge);
    let h_T_star = max(0.0, h_T + zb_T - zb_edge);

    if (h_B_star <= EPSILON_H && h_T_star <= EPSILON_H) {
        return vec3<f32>(0.0);
    }

    let v_B = select(0.0, hv_B / max(h_B, EPSILON_H), h_B > EPSILON_H);
    let v_T = select(0.0, hv_T / max(h_T, EPSILON_H), h_T > EPSILON_H);

    let c_B = sqrt(g * h_B_star);
    let c_T = sqrt(g * h_T_star);

    let a_plus = max(0.0, max(v_B + c_B, v_T + c_T));
    let a_minus = min(0.0, min(v_B - c_B, v_T - c_T));
    let denom = a_plus - a_minus;

    if (denom <= 1e-6) {
        return vec3<f32>(0.0);
    }

    let hu_B_star = select(0.0, (h_B_star / max(h_B, EPSILON_H)) * hu_B, h_B > EPSILON_H);
    let hu_T_star = select(0.0, (h_T_star / max(h_T, EPSILON_H)) * hu_T, h_T > EPSILON_H);
    let hv_B_star = h_B_star * v_B;
    let hv_T_star = h_T_star * v_T;

    let F_B = physical_flux_y(h_B_star, hu_B_star, hv_B_star, g);
    let F_T = physical_flux_y(h_T_star, hu_T_star, hv_T_star, g);

    let U_B = vec3<f32>(h_B_star, hu_B_star, hv_B_star);
    let U_T = vec3<f32>(h_T_star, hu_T_star, hv_T_star);

    return (a_plus * F_B - a_minus * F_T + a_plus * a_minus * (U_T - U_B)) / denom;
}

@compute @workgroup_size(16, 16)
fn swe_step_main(@builtin(global_invocation_id) global_id: vec3<u32>) {
    let x = i32(global_id.x);
    let y = i32(global_id.y);

    if (global_id.x >= params.grid_dim.x || global_id.y >= params.grid_dim.y) {
        return;
    }

    let coord = vec2<i32>(x, y);
    let center = sample_state(coord);
    let bed_c = sample_bed(coord);

    let h_C = center.x;
    let hu_C = center.y;
    let hv_C = center.z;
    let tracer_C = center.w;
    let zb_C = bed_c.x;

    // Neighboring cell states
    let state_W = sample_state(coord + vec2<i32>(-1, 0));
    let bed_W = sample_bed(coord + vec2<i32>(-1, 0));
    let state_E = sample_state(coord + vec2<i32>(1, 0));
    let bed_E = sample_bed(coord + vec2<i32>(1, 0));
    let state_S = sample_state(coord + vec2<i32>(0, -1));
    let bed_S = sample_bed(coord + vec2<i32>(0, -1));
    let state_N = sample_state(coord + vec2<i32>(0, 1));
    let bed_N = sample_bed(coord + vec2<i32>(0, 1));

    let g = params.gravity;
    let dt = params.dt;
    let dx = params.dx;
    let inv_dx = 1.0 / dx;

    // Numerical interface fluxes
    let flux_west = compute_interface_flux_x(
        state_W.x, state_W.y, state_W.z, bed_W.x,
        h_C, hu_C, hv_C, zb_C, g
    );
    let flux_east = compute_interface_flux_x(
        h_C, hu_C, hv_C, zb_C,
        state_E.x, state_E.y, state_E.z, bed_E.x, g
    );
    let flux_south = compute_interface_flux_y(
        state_S.x, state_S.y, state_S.z, bed_S.x,
        h_C, hu_C, hv_C, zb_C, g
    );
    let flux_north = compute_interface_flux_y(
        h_C, hu_C, hv_C, zb_C,
        state_N.x, state_N.y, state_N.z, bed_N.x, g
    );

    // Bed slope source term via centered difference
    let dzb_dx = (bed_E.x - bed_W.x) * (0.5 * inv_dx);
    let dzb_dy = (bed_N.x - bed_S.x) * (0.5 * inv_dx);
    let source_slope_x = -g * h_C * dzb_dx;
    let source_slope_y = -g * h_C * dzb_dy;

    // Kinematic eddy diffusion laplacian: ν * ∇²(hu)
    let laplacian_hu = (state_W.y + state_E.y + state_S.y + state_N.y - 4.0 * hu_C) * (inv_dx * inv_dx);
    let laplacian_hv = (state_W.z + state_E.z + state_S.z + state_N.z - 4.0 * hv_C) * (inv_dx * inv_dx);

    // Explicit update for depth and raw intermediate momentum
    let div_flux_h = (flux_east.x - flux_west.x + flux_north.x - flux_south.x) * inv_dx;
    let net_source_mass = params.rain_rate - params.infiltration;
    var h_new = max(0.0, h_C - dt * div_flux_h + dt * net_source_mass);

    var hu_raw = hu_C - dt * ((flux_east.y - flux_west.y + flux_north.y - flux_south.y) * inv_dx)
        + dt * source_slope_x + dt * params.viscosity * laplacian_hu;
    var hv_raw = hv_C - dt * ((flux_east.z - flux_west.z + flux_north.z - flux_south.z) * inv_dx)
        + dt * source_slope_y + dt * params.viscosity * laplacian_hv;

    // Semi-implicit Manning bed friction to eliminate numerical instability at shallow depths
    var hu_new = 0.0;
    var hv_new = 0.0;

    if (h_new > EPSILON_H) {
        let u_raw = hu_raw / h_new;
        let v_raw = hv_raw / h_new;
        let speed = sqrt(u_raw * u_raw + v_raw * v_raw);

        let local_n = params.manning_n * max(0.1, bed_c.y);
        let h_pow_4_3 = pow(h_new, 4.0 / 3.0);
        let friction_drag = g * (local_n * local_n) * speed / max(h_pow_4_3, 1e-4);
        let dampening = 1.0 / (1.0 + dt * friction_drag);

        hu_new = hu_raw * dampening;
        hv_new = hv_raw * dampening;
    }

    // Passive tracer advection (e.g. tannin concentration from leaf litter)
    let div_tracer = (
        select(0.0, flux_east.x * tracer_C, flux_east.x >= 0.0) + select(0.0, flux_east.x * state_E.w, flux_east.x < 0.0)
        - (select(0.0, flux_west.x * state_W.w, flux_west.x >= 0.0) + select(0.0, flux_west.x * tracer_C, flux_west.x < 0.0))
        + select(0.0, flux_north.x * tracer_C, flux_north.x >= 0.0) + select(0.0, flux_north.x * state_N.w, flux_north.x < 0.0)
        - (select(0.0, flux_south.x * state_S.w, flux_south.x >= 0.0) + select(0.0, flux_south.x * tracer_C, flux_south.x < 0.0))
    ) * inv_dx;

    let tracer_new = select(0.0, max(0.0, (tracer_C * h_C - dt * div_tracer) / max(h_new, EPSILON_H)), h_new > EPSILON_H);

    textureStore(state_next, coord, vec4<f32>(h_new, hu_new, hv_new, tracer_new));
}

viewport_library_wgsl.water:
// HMC water surface — a bounded transparent surface that consumes the shared
// scene depth contract without writing depth. Terrain and entities therefore
// retain ownership of authoritative visibility and picking.

struct Camera {
    view_projection: mat4x4<f32>,
    yaw: f32,
    pitch: f32,
    zoom: f32,
    tensor_mode: u32,
    _padding0: vec4<f32>,
    _padding1: vec4<f32>,
    _padding2: vec4<f32>,
};
@group(0) @binding(0) var<uniform> camera: Camera;
@group(1) @binding(0) var<uniform> model: mat4x4<f32>;

struct WaterUniform {
    colour_alpha: vec4<f32>,
    wave: vec4<f32>, // time, amplitude, frequency, shore-width
    quality: vec4<f32>, // tier, reflection, foam, shore response
    viewport: vec4<f32>, // width, height, depth epsilon, reserved
};
@group(2) @binding(0) var<uniform> water: WaterUniform;

struct VertexOutput {
    @builtin(position) clip_position: vec4<f32>,
    @location(0) uv: vec2<f32>,
    @location(1) stable_normal: vec3<f32>,
    @location(2) world_position: vec3<f32>,
    @location(3) shore_distance: f32,
    @location(4) shore_scale: f32,
};

@vertex
fn vertex_main(
    @location(0) position: vec3<f32>,
    @location(1) uv: vec2<f32>,
    @location(2) shore: vec2<f32>,
) -> VertexOutput {
    var output: VertexOutput;
    let phase_x = position.x * water.wave.z + water.wave.x * 0.85;
    let phase_z = position.z * water.wave.z * 0.83 - water.wave.x * 0.62;
    let sin_x = sin(phase_x);
    let cos_x = cos(phase_x);
    let sin_z = sin(phase_z);
    let cos_z = cos(phase_z);
    let shore_width = clamp(shore.y * 0.22, 0.0001, 0.008);
    let shore_fade = select(1.0, smoothstep(0.0, shore_width, shore.x), shore.y > 0.000001);
    let height = sin_x * cos_z * water.wave.y * shore_fade;
    // Analytic derivatives keep normals stable across tessellation and avoid a
    // second geometry upload just to carry a normal stream.
    let d_height_x = cos_x * cos_z * water.wave.y * water.wave.z * shore_fade;
    let d_height_z = -sin_x * sin_z * water.wave.y * water.wave.z * 0.83 * shore_fade;
    let local = position + vec3<f32>(
        0.0,
        height,
        0.0,
    );
    let world = model * vec4<f32>(local, 1.0);
    output.clip_position = camera.view_projection * world;
    output.world_position = world.xyz;
    output.shore_distance = shore.x;
    output.shore_scale = shore.y;
    output.uv = uv;
    output.stable_normal = normalize((model * vec4<f32>(-d_height_x, 1.0, -d_height_z, 0.0)).xyz);
    return output;
}

@fragment
fn fragment_main(input: VertexOutput) -> @location(0) vec4<f32> {
    // The render pass uses the same scene depth attachment with LessEqual and
    // depth writes disabled. This second guard makes the ownership explicit in
    // the shader contract and leaves a small tolerance for raster precision.
    // Fragment position is already rasterised: Z is device depth and W is
    // reciprocal clip W. Dividing them again incorrectly clips distant water.
    let water_depth = input.clip_position.z;
    if (water_depth > 1.0 + water.viewport.z || water_depth < 0.0) {
        discard;
    }

    let p = input.world_position.xz;
    let time = water.wave.x;
    let detail_frequency = max(water.wave.z, 0.001);
    let ripple = 0.5 + 0.5 * sin((p.x * 1.9 + p.y * 1.3) * detail_frequency + time * 1.7);
    let fine_scale = select(0.0, 0.035, water.quality.x >= 0.5);
    let fine = vec3<f32>(sin(p.x * detail_frequency * 3.1 + time * 1.2), 0.0, cos(p.y * detail_frequency * 2.7 - time * 0.9)) * fine_scale;
    let normal = normalize(input.stable_normal + fine);
    let eye = camera._padding0.yzw;
    let view_vector = eye - input.world_position;
    let view_dir = view_vector / max(length(view_vector), 0.00001);
    let n_dot_v = clamp(abs(dot(normal, view_dir)), 0.0, 1.0);
    let fresnel = 0.02 + 0.98 * pow(1.0 - n_dot_v, 5.0);
    let reflection = fresnel * water.quality.y;

    // Mesh boundary distance is a shoreline attribute, not measured bathymetry.
    // It follows curved banks and keeps foam off the middle of flat surfaces.
    let shore_width = clamp(input.shore_scale * 0.22, 0.0001, 0.008);
    let shore = select(0.0, 1.0 - smoothstep(0.0, shore_width, input.shore_distance), input.shore_scale > 0.000001);
    let foam_pattern = smoothstep(0.30, 0.80, ripple);
    let foam = shore * foam_pattern * water.quality.z * water.quality.w * 0.60;
    let depth_factor = select(0.65, 1.0 - exp(-max(input.shore_distance, 0.0) / max(input.shore_scale, 0.0001) * 2.5), input.shore_scale > 0.000001);
    let shallow = mix(water.colour_alpha.rgb, vec3<f32>(0.34, 0.47, 0.33), 0.28);
    let deep = water.colour_alpha.rgb * 0.70;
    let base_tint = mix(shallow, deep, depth_factor) * (0.96 + ripple * 0.08);
    let reflected_ray = reflect(-view_dir, normal);
    let reflected_tint = mix(vec3<f32>(0.68, 0.77, 0.78), vec3<f32>(0.30, 0.53, 0.76), clamp(reflected_ray.y, 0.0, 1.0));
    let foam_tint = vec3<f32>(0.76, 0.81, 0.73);
    let tier_scale = select(1.0, 0.92, water.quality.x < 0.5);
    let tint = mix(base_tint, reflected_tint, reflection * tier_scale);
    var sun = vec3<f32>(camera._padding1.w, camera._padding2.x, camera._padding2.y);
    if (dot(sun, sun) < 0.01) { sun = vec3<f32>(0.45, 0.8, 0.55); }
    let half_vector = normalize(normalize(sun) + view_dir + vec3<f32>(0.000001));
    let glint = pow(clamp(dot(normal, half_vector), 0.0, 1.0), 96.0) * water.quality.y * 0.55;
    let final_tint = mix(tint, foam_tint, clamp(foam, 0.0, 1.0)) + vec3<f32>(1.0, 0.91, 0.71) * glint;
    let final_alpha = clamp(water.colour_alpha.a * mix(0.38, 1.0, depth_factor) + foam * 0.12 + reflection * 0.12, 0.0, 1.0);
    return vec4<f32>(final_tint, final_alpha);
}
